def q429(
    parameter_count,
    batch,
    prompt_tokens,
    weight_bytes,
    peak_flops,
    bandwidth,
):
    traffic = parameter_count * weight_bytes
    result = {}
    for name, tokens in (
        ("prefill", batch * prompt_tokens),
        ("decode", batch),
    ):
        compute = 2 * parameter_count * tokens / peak_flops
        memory = traffic / bandwidth
        result[name] = {
            "bound": "compute" if compute >= memory else "memory",
            "seconds": max(compute, memory),
        }
    return result
